def main():
    if len(sys.argv) != 2 or sys.argv[1].upper() not in CASES:
        raise SystemExit("Usage: python3 tests/test-presence-history.py M156|M157|M158|M159|M160|M161|M162|M163")
    exec(compile(CASES[sys.argv[1].upper()], str(Path(__file__).resolve()), "exec"),
         {"__name__": "__main__", "__file__": __file__})

if __name__ == "__main__":
    main()
